                schema: '<svg viewBox="0 0 400 160" xmlns="http://www.w3.org/2000/svg" style="width:100%;max-width:400px;display:block;margin:0 auto"><text x="200" y="14" text-anchor="middle" font-size="10" font-weight="800" fill="currentColor">HYDROGRAMME DE CRUE</text><line x1="30" y1="140" x2="380" y2="140" stroke="currentColor" stroke-width="1.5" opacity=".5"/><line x1="30" y1="140" x2="30" y2="20" stroke="currentColor" stroke-width="1.5" opacity=".5"/><polyline points="30,135 60,132 90,125 120,100 150,60 180,35 210,50 240,75 270,100 300,118 330,128 360,133 380,135" fill="none" stroke="#0EA5E9" stroke-width="2.5"/><line x1="180" y1="35" x2="180" y2="140" stroke="#EF4444" stroke-width="1.5" stroke-dasharray="4,3"/><text x="182" y="32" font-size="8" fill="#EF4444" font-weight="700">Qp</text><line x1="30" y1="35" x2="180" y2="35" stroke="#EF4444" stroke-width="1" stroke-dasharray="3,2" opacity=".5"/><text x="5" y="38" font-size="7" fill="#EF4444">Qp</text><text x="200" y="155" font-size="8" fill="currentColor" opacity=".7">Temps (h) →</text><text x="110" y="155" font-size="7" fill="#0EA5E9">← Tm →</text><line x1="90" y1="148" x2="90" y2="142" stroke="#0EA5E9" stroke-width="1.5"/><line x1="180" y1="148" x2="180" y2="142" stroke="#0EA5E9" stroke-width="1.5"/><text x="5" y="80" font-size="7" fill="currentColor" opacity=".6">Q</text><text x="250" y="90" font-size="7.5" fill="currentColor" opacity=".7">Récession</text><text x="82" y="90" font-size="7.5" fill="currentColor" opacity=".7">Montée</text></svg>',
