                schema: '<svg viewBox="0 0 400 130" xmlns="http://www.w3.org/2000/svg" style="width:100%;max-width:400px;display:block;margin:0 auto"><defs><marker id="farr" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0,0 L0,6 L6,3 Z" fill="currentColor" opacity=".5"/></marker></defs><text x="200" y="13" text-anchor="middle" font-size="10" font-weight="800" fill="currentColor">FILIÈRES DE TRAITEMENT AEP</text><text x="10" y="32" font-size="8" font-weight="700" fill="#0369A1">Eau souterraine :</text><rect x="10" y="36" width="55" height="22" rx="3" fill="rgba(14,165,233,.15)" stroke="#0EA5E9" stroke-width="1"/><text x="37" y="51" text-anchor="middle" font-size="7.5" fill="currentColor">Aération</text><line x1="65" y1="47" x2="75" y2="47" stroke="currentColor" stroke-width="1.5" marker-end="url(#farr)" opacity=".5"/><rect x="75" y="36" width="55" height="22" rx="3" fill="rgba(14,165,233,.15)" stroke="#0EA5E9" stroke-width="1"/><text x="102" y="51" text-anchor="middle" font-size="7.5" fill="currentColor">Filtration</text><line x1="130" y1="47" x2="140" y2="47" stroke="currentColor" stroke-width="1.5" marker-end="url(#farr)" opacity=".5"/><rect x="140" y="36" width="55" height="22" rx="3" fill="rgba(22,163,74,.20)" stroke="#16A34A" stroke-width="1.5"/><text x="167" y="51" text-anchor="middle" font-size="7.5" font-weight="700" fill="#15803D">Chloration</text><text x="10" y="75" font-size="8" font-weight="700" fill="#D97706">Eau de surface :</text><rect x="10" y="79" width="50" height="22" rx="3" fill="rgba(234,88,12,.12)" stroke="#F97316" stroke-width="1"/><text x="35" y="94" text-anchor="middle" font-size="7" fill="currentColor">Coag/Floc</text><line x1="60" y1="90" x2="68" y2="90" stroke="currentColor" stroke-width="1.5" marker-end="url(#farr)" opacity=".5"/><rect x="68" y="79" width="45" height="22" rx="3" fill="rgba(234,88,12,.12)" stroke="#F97316" stroke-width="1"/><text x="90" y="94" text-anchor="middle" font-size="7" fill="currentColor">Décantat.</text><line x1="113" y1="90" x2="121" y2="90" stroke="currentColor" stroke-width="1.5" marker-end="url(#farr)" opacity=".5"/><rect x="121" y="79" width="45" height="22" rx="3" fill="rgba(234,88,12,.12)" stroke="#F97316" stroke-width="1"/><text x="143" y="94" text-anchor="middle" font-size="7" fill="currentColor">Filtration</text><line x1="166" y1="90" x2="174" y2="90" stroke="currentColor" stroke-width="1.5" marker-end="url(#farr)" opacity=".5"/><rect x="174" y="79" width="45" height="22" rx="3" fill="rgba(22,163,74,.20)" stroke="#16A34A" stroke-width="1.5"/><text x="196" y="94" text-anchor="middle" font-size="7" font-weight="700" fill="#15803D">Chloration</text><text x="10" y="118" font-size="7.5" fill="currentColor" opacity=".7">Avancée : + Ozonation + CAG (micropolluants) | Désalinisation : + OI (4–8 kWh/m³)</text></svg>',
