                schema: '<svg viewBox="0 0 480 190" xmlns="http://www.w3.org/2000/svg" style="width:100%;display:block"><text x="240" y="14" text-anchor="middle" font-size="10" font-weight="800" fill="currentColor" opacity=".6">PÉRIMÈTRES DE PROTECTION D\'UN CAPTAGE AEP</text><circle cx="240" cy="110" r="130" fill="rgba(234,88,12,.06)" stroke="rgba(234,88,12,.3)" stroke-width="1.5" stroke-dasharray="6,4"/><text x="240" y="22" text-anchor="middle" font-size="8" fill="#EA580C" font-weight="700">PPE — périmètre éloigné (bassin alimentation)</text><circle cx="240" cy="110" r="85" fill="rgba(245,158,11,.1)" stroke="rgba(245,158,11,.5)" stroke-width="1.5" stroke-dasharray="4,3"/><text x="240" y="32" text-anchor="middle" font-size="8" fill="#B45309" font-weight="700">PPR — 50 jours de transit</text><circle cx="240" cy="110" r="35" fill="rgba(22,163,74,.15)" stroke="rgba(22,163,74,.6)" stroke-width="2"/><text x="240" y="100" text-anchor="middle" font-size="8" font-weight="700" fill="#15803D">PPI</text><text x="240" y="112" text-anchor="middle" font-size="7" fill="#15803D">clôturé</text><text x="240" y="123" text-anchor="middle" font-size="7" fill="#15803D">propriété collectivité</text><rect x="226" y="125" width="28" height="45" rx="3" fill="rgba(3,105,161,.3)" stroke="rgba(3,105,161,.7)" stroke-width="1.5"/><text x="240" y="148" text-anchor="middle" font-size="7" font-weight="700" fill="#0369A1">FORAGE</text><circle cx="240" cy="157" r="3" fill="#0369A1"/><line x1="240" y1="160" x2="240" y2="175" stroke="#0369A1" stroke-width="2"/><text x="250" y="172" font-size="7" fill="#0369A1">crépines</text></svg>',
