/* ─── Assainissement du texte pour jsPDF (polices standard = WinAnsi/Latin-1) ───
   Les lettres grecques, symboles math et emojis ne sont pas supportés par les
   polices standard de jsPDF : ils cassent le calcul de largeur de texte et
   provoquent un chevauchement en cascade sur tout le reste de la ligne.
   On les remplace par un équivalent texte lisible, et on retire tout le reste. */
var _PDF_SYMBOL_MAP = {
  'Δ':'D', 'Π':'Pi', 'Σ':'somme', 'α':'alpha', 'γ':'gamma', 'η':'eta', 'λ':'lambda',
  'μ':'mu', 'ν':'nu', 'ξ':'xi', 'π':'pi', 'ρ':'rho', 'σ':'sigma', 'ω':'omega',
  '∂':'d', '∇':'grad', '√':'racine', '∝':'prop. a', '≠':'!=',
  '≤':'<=', '≥':'>=', '←':'<-', '→':'->', '↓':'(bas)', '↑':'(haut)',
  '─':'-', '═':'=',
  '⁰':'0','⁴':'4','⁵':'5','⁶':'6','⁷':'7','⁸':'8','⁹':'9','⁺':'+','⁻':'-',
  '₀':'0','₁':'1','₂':'2','₃':'3','₄':'4','₅':'5','₆':'6','₇':'7','₈':'8','₉':'9'
};
/* Caractères hors Latin-1 mais quand même supportés par l'encodage WinAnsi
   des polices standard jsPDF (tiret cadratin, puce, points de suspension...) */
var _PDF_WINANSI_EXTRA = {
  0x2013:1, 0x2014:1, 0x2018:1, 0x2019:1, 0x201C:1, 0x201D:1,
  0x2022:1, 0x2026:1, 0x2030:1, 0x2039:1, 0x203A:1, 0x20AC:1, 0x2122:1
};
function _pdfSanitize(str) {
  if (!str) return '';
  var out = '';
  for (var i = 0; i < str.length; i++) {
    var ch = str[i];
    var cp = str.codePointAt(i);
    if (_PDF_SYMBOL_MAP[ch] !== undefined) { out += ' ' + _PDF_SYMBOL_MAP[ch] + ' '; continue; }
    if (cp <= 0xFF || _PDF_WINANSI_EXTRA[cp]) { out += ch; continue; }
    /* caractère hors Latin-1 (emoji, pictogramme, drapeau...) : on l'ignore */
    if (cp > 0xFFFF) i++; /* sauter le 2e élément d'une paire surrogate */
  }
  out = out.replace(/^[\s:.\-–—]+/, '').replace(/\s{2,}/g, ' ').trim();
  return out;
}

/* ─── Découpage du texte en segments stylés (surlignage) ───
   - MOTS EN MAJUSCULES (déjà utilisés dans le contenu pour l'emphase) → orange
   - Valeurs numériques + unité (ex: "9 810 Pa", "1 000 kg/m³") → bleu        */
function _fichePdfSegments(rawText) {
  var text = _pdfSanitize(rawText);
  var NUM_RE = /\d[\d\s,.  ]*\s?(?:kg\/m³|m³\/[hs]|L\/s|Pa\.?s|m²\/s|kPa|MPa|GPa|N\/m³|m\s?CE|cm\s?CE|°C|mm|cm|km|m\/s²?|m³|N\b|Pa\b|bar|%)/g;
  var segs = [], lastIdx = 0, m;
  while ((m = NUM_RE.exec(text))) {
    if (m.index > lastIdx) segs.push({ t: text.slice(lastIdx, m.index), style: 'normal' });
    segs.push({ t: m[0], style: 'num' });
    lastIdx = m.index + m[0].length;
  }
  if (lastIdx < text.length) segs.push({ t: text.slice(lastIdx), style: 'normal' });

  var CAPS_RE = /\b[A-ZÀÂÉÈÊËÎÏÔŒÙÛÜŸÇ]{3,}\b/g;
  var finalSegs = [];
  segs.forEach(function(s) {
    if (s.style !== 'normal') { finalSegs.push(s); return; }
    var idx = 0, cm;
    CAPS_RE.lastIndex = 0;
    while ((cm = CAPS_RE.exec(s.t))) {
      if (cm.index > idx) finalSegs.push({ t: s.t.slice(idx, cm.index), style: 'normal' });
      finalSegs.push({ t: cm[0], style: 'caps' });
      idx = cm.index + cm[0].length;
    }
    if (idx < s.t.length) finalSegs.push({ t: s.t.slice(idx), style: 'normal' });
  });
  return finalSegs;
}

/* ─── Rendu d'un texte multi-style avec retour à la ligne automatique ───
   Renvoie le y final (bas du bloc) ── */
function _drawRichText(doc, text, x0, y0, maxWidth, lineHeight, colors) {
  var segments = _fichePdfSegments(text);
  var x = x0, y = y0;
  doc.setFontSize(9.3);
  doc.setFont('helvetica', 'normal');
  var spaceW = doc.getTextWidth(' ');

  segments.forEach(function(seg) {
    var tokens = seg.t.split(/(\s+)/).filter(function(w){ return w.length; });
    tokens.forEach(function(w) {
      if (/^\s+$/.test(w)) { x += spaceW; return; }
      var bold = seg.style !== 'normal';
      doc.setFont('helvetica', bold ? 'bold' : 'normal');
      var ww = doc.getTextWidth(w);
      if (x + ww > x0 + maxWidth) { x = x0; y += lineHeight; }
      if (seg.style === 'num') {
        doc.setFillColor.apply(doc, colors.numBg);
        doc.rect(x - 0.4, y - 3.1, ww + 0.8, 4, 'F');
        doc.setTextColor.apply(doc, colors.num);
      } else if (seg.style === 'caps') {
        doc.setFillColor.apply(doc, colors.capsBg);
        doc.rect(x - 0.4, y - 3.1, ww + 0.8, 4, 'F');
        doc.setTextColor.apply(doc, colors.caps);
      } else {
        doc.setTextColor.apply(doc, colors.normal);
      }
      doc.text(w, x, y);
      x += ww + spaceW;
    });
  });
  doc.setFont('helvetica', 'normal');
  return y;
}

/* ─── Mesure le nombre de lignes qu'occupera un texte riche (pour la pagination) ─── */
function _richTextLineCount(doc, text, maxWidth) {
  var segments = _fichePdfSegments(text);
  doc.setFontSize(9.3);
  var x = 0, lines = 1;
  var spaceW = doc.getTextWidth(' ');
  segments.forEach(function(seg) {
    var tokens = seg.t.split(/(\s+)/).filter(function(w){ return w.length; });
    tokens.forEach(function(w) {
      if (/^\s+$/.test(w)) { x += spaceW; return; }
      doc.setFont('helvetica', seg.style !== 'normal' ? 'bold' : 'normal');
      var ww = doc.getTextWidth(w);
      if (x + ww > maxWidth) { x = 0; lines++; }
      x += ww + spaceW;
    });
  });
  doc.setFont('helvetica', 'normal');
  return lines;
}

var _FICHE_COLORS = {
  normal: [30, 38, 34], num: [12, 90, 150], numBg: [222, 238, 250],
  caps: [180, 70, 10], capsBg: [253, 232, 210]
};

/* ─── Construit le contenu PDF d'UN chapitre, à partir de y, retourne y final ─── */
function _svgStringToPng(svgStr, w, h, cb) {
  var textColor = (getComputedStyle(document.documentElement).getPropertyValue('--c-text') || '').trim() || '#1e293b';
  var resolved = svgStr.replace(/currentColor/g, textColor);
  var blob = new Blob([resolved], { type:'image/svg+xml;charset=utf-8' });
  var url = URL.createObjectURL(blob);
  var img = new Image();
  img.onload = function() {
    var canvas = document.createElement('canvas');
    var sc = 2;
    canvas.width = w * sc; canvas.height = h * sc;
    var ctx = canvas.getContext('2d');
    ctx.scale(sc, sc);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, w, h);
    ctx.drawImage(img, 0, 0, w, h);
    URL.revokeObjectURL(url);
    cb({ dataUrl: canvas.toDataURL('image/png'), w: w, h: h });
  };
  img.onerror = function() { URL.revokeObjectURL(url); cb(null); };
  img.src = url;
}

function _svgDimensions(svgStr) {
  var tmp = document.createElement('div');
  tmp.innerHTML = svgStr;
  var svg = tmp.querySelector('svg');
  var vb = svg ? svg.getAttribute('viewBox') : null;
  if (vb) { var p = vb.split(/\s+/); return { w: parseFloat(p[2]) || 340, h: parseFloat(p[3]) || 200 }; }
  return { w: 340, h: 200 };
}

function _preconvertSchemas(chaps, cb) {
  var map = {};
  var pending = 0;
  chaps.forEach(function(c) {
    if (c.fiche && c.fiche.schema) pending++;
    if (c.fiche && c.fiche.sections) c.fiche.sections.forEach(function(sec) { if (sec && sec.schema) pending++; });
    if (c.exercices) c.exercices.forEach(function(ex) { if (ex.schema) pending++; });
  });
  if (!pending) { cb(map); return; }
  chaps.forEach(function(c) {
    if (c.fiche && c.fiche.schema) {
      var dim = _svgDimensions(c.fiche.schema);
      _svgStringToPng(c.fiche.schema, dim.w, dim.h, function(png) {
        if (png) map[c.id] = png;
        pending--;
        if (!pending) cb(map);
      });
    }
    if (c.fiche && c.fiche.sections) {
      c.fiche.sections.forEach(function(sec, si) {
        if (!sec || !sec.schema) return;
        var key = c.id + '_sec_' + si;
        var dim = _svgDimensions(sec.schema);
        _svgStringToPng(sec.schema, dim.w, dim.h, function(png) {
          if (png) map[key] = png;
          pending--;
          if (!pending) cb(map);
        });
      });
    }
    if (c.exercices) {
      c.exercices.forEach(function(ex) {
        if (!ex.schema) return;
        var dim = _svgDimensions(ex.schema);
        _svgStringToPng(ex.schema, dim.w, dim.h, function(png) {
          if (png) map['ex_' + ex.id] = png;
          pending--;
          if (!pending) cb(map);
        });
      });
    }
  });
}

function _renderFichePdfBlock(doc, m, c, y, MARGIN, cW, schemaMap, headerInfo) {
  var schemaPng = schemaMap ? (schemaMap[c.id] || null) : null;
  var fi = c.fiche;
  var W = MARGIN * 2 + cW;

  /* Palette fixe Hydrocalc */
  var C_DARK  = [18, 59, 114];    /* #123B72 */
  var C_ACC   = [8, 127, 234];    /* #087FEA */
  var C_LBLUE = [220, 238, 255];  /* #DCEEFF */
  var C_TEXT  = [39, 49, 61];     /* #27313D */
  var C_GRAY  = [104, 117, 133];  /* #687585 */
  var C_LGRAY = [244, 247, 250];  /* #F4F7FA */
  var PAGE_H = 275, RESUME_Y = 22;

  function newPage() {
    doc.addPage();
    if (headerInfo) _pdfFicheHeader(doc, W, MARGIN, headerInfo.color, headerInfo.title, headerInfo.subtitle);
    y = RESUME_Y;
  }

  function checkPage(needed) {
    if (y + needed > PAGE_H) newPage();
  }

  function sectionLabel(label) {
    doc.setFont('helvetica', 'bold'); doc.setFontSize(9.5);
    doc.setTextColor(C_DARK[0], C_DARK[1], C_DARK[2]);
    doc.text(label.toUpperCase(), MARGIN, y);
    doc.setDrawColor(C_ACC[0], C_ACC[1], C_ACC[2]);
    doc.setLineWidth(0.5);
    doc.line(MARGIN, y + 2, MARGIN + cW, y + 2);
    y += 8;
  }

  /* ── 1. Badge matière + grand titre ── */
  checkPage(32);
  var badgeText = _pdfSanitize(m.name);
  doc.setFont('helvetica', 'bold'); doc.setFontSize(7.5);
  var badgeW = doc.getTextWidth(badgeText) + 10;
  doc.setFillColor(C_LBLUE[0], C_LBLUE[1], C_LBLUE[2]);
  doc.roundedRect(MARGIN, y, badgeW, 6.5, 3, 3, 'F');
  doc.setTextColor(C_DARK[0], C_DARK[1], C_DARK[2]);
  doc.text(badgeText, MARGIN + 5, y + 4.8);
  y += 10;

  doc.setFont('helvetica', 'bold'); doc.setFontSize(18);
  doc.setTextColor(C_DARK[0], C_DARK[1], C_DARK[2]);
  var titreLines = doc.splitTextToSize(_pdfSanitize(c.titre), cW);
  titreLines.forEach(function(l) { doc.text(l, MARGIN, y); y += 9; });

  doc.setDrawColor(C_ACC[0], C_ACC[1], C_ACC[2]);
  doc.setLineWidth(1.5);
  doc.line(MARGIN, y, MARGIN + 32, y);
  doc.setLineWidth(0.25);
  doc.setDrawColor(C_LBLUE[0], C_LBLUE[1], C_LBLUE[2]);
  doc.line(MARGIN + 34, y, MARGIN + cW, y);
  y += 9;

  /* ── 2. Résumé / intro ── */
  if (fi.intro) {
    var LH = 5.3;
    doc.setFont('helvetica', 'italic'); doc.setFontSize(9.5);
    var introLines = doc.splitTextToSize(_pdfSanitize(fi.intro), cW - 16);
    checkPage(introLines.length * LH + 14);
    doc.setFillColor(C_LGRAY[0], C_LGRAY[1], C_LGRAY[2]);
    doc.roundedRect(MARGIN, y, cW, introLines.length * LH + 10, 3, 3, 'F');
    doc.setFillColor(C_ACC[0], C_ACC[1], C_ACC[2]);
    doc.roundedRect(MARGIN, y, 2.5, introLines.length * LH + 10, 1.5, 1.5, 'F');
    doc.setTextColor(C_GRAY[0], C_GRAY[1], C_GRAY[2]);
    introLines.forEach(function(l, i) { doc.text(l, MARGIN + 8, y + 7 + i * LH); });
    y += introLines.length * LH + 16;
  }

  /* ── 3. Sections ── */
  if (fi.sections && fi.sections.length) {
    checkPage(16);
    sectionLabel('Contenu du cours');

    fi.sections.forEach(function(sec, si) {
      var titreSection = typeof sec === 'string' ? sec : sec.titre;
      var texteSection = typeof sec === 'string' ? '' : (sec.texte || '');
      var schemaSection = typeof sec === 'string' ? null : (sec.schema || null);

      checkPage(22);
      doc.setFont('helvetica', 'bold'); doc.setFontSize(11);
      doc.setTextColor(C_DARK[0], C_DARK[1], C_DARK[2]);
      var titSecLines = doc.splitTextToSize((si + 1) + '. ' + _pdfSanitize(titreSection), cW);
      titSecLines.forEach(function(l) { doc.text(l, MARGIN, y); y += 6.5; });
      doc.setDrawColor(C_LBLUE[0], C_LBLUE[1], C_LBLUE[2]);
      doc.setLineWidth(0.25);
      doc.line(MARGIN, y, MARGIN + cW, y);
      y += 6;

      if (texteSection) {
        texteSection.split(/\n{2,}/).forEach(function(bloc) {
          var blocTrim = bloc.trim();
          if (!blocTrim) return;
          if (/^\|.+\|/m.test(blocTrim)) {
            y = _pdfRenderMarkdownTable(doc, blocTrim, MARGIN, y, cW, C_DARK, C_LBLUE, checkPage);
            return;
          }
          var cleanBloc = blocTrim
            .replace(/\*\*(.+?)\*\*/g, '$1').replace(/\*(.+?)\*/g, '$1')
            .replace(/`(.+?)`/g, '$1').replace(/^#{1,4}\s/gm, '')
            .replace(/^[•\-\*]\s/gm, '  • ');
          var paraClean = _pdfSanitize(cleanBloc);
          if (!paraClean) return;
          doc.setFont('helvetica', 'normal'); doc.setFontSize(9.5);
          doc.setTextColor(C_TEXT[0], C_TEXT[1], C_TEXT[2]);
          var paraLines = doc.splitTextToSize(paraClean, cW);
          checkPage(Math.min(paraLines.length * 5.5 + 4, 60));
          paraLines.forEach(function(l) {
            if (y + 5.5 > PAGE_H) newPage();
            doc.text(l, MARGIN, y); y += 5.5;
          });
          y += 5;
        });
      }

      if (schemaSection && schemaMap) {
        var secPng = schemaMap[c.id + '_sec_' + si];
        if (secPng && secPng.dataUrl) {
          var secImgH = Math.round(secPng.h * (cW / secPng.w));
          checkPage(secImgH + 16);
          doc.setDrawColor(C_LBLUE[0], C_LBLUE[1], C_LBLUE[2]);
          doc.setLineWidth(0.3);
          doc.roundedRect(MARGIN, y, cW, secImgH + 4, 2, 2, 'D');
          doc.addImage(secPng.dataUrl, 'PNG', MARGIN + 2, y + 2, cW - 4, secImgH);
          y += secImgH + 8;
          doc.setFont('helvetica', 'italic'); doc.setFontSize(8);
          doc.setTextColor(C_GRAY[0], C_GRAY[1], C_GRAY[2]);
          doc.text('Figure ' + (si + 1) + '  —  ' + _pdfSanitize(titreSection), MARGIN + cW / 2, y, { align: 'center' });
          y += 8;
        }
      }
      y += 5;
    });
    y += 2;
  }

  /* ── 4. Points clés ── */
  if (fi.points && fi.points.length) {
    checkPage(16);
    sectionLabel('Points cles');
    fi.points.forEach(function(p) {
      var items = (typeof p === 'string') ? p.split(' | ') : [p];
      items.forEach(function(part) {
        part = _pdfSanitize(part.trim());
        if (!part) return;
        doc.setFont('helvetica', 'normal'); doc.setFontSize(9.5);
        doc.setTextColor(C_TEXT[0], C_TEXT[1], C_TEXT[2]);
        var pLines = doc.splitTextToSize(part, cW - 10);
        checkPage(pLines.length * 5.5 + 4);
        doc.setFillColor(C_ACC[0], C_ACC[1], C_ACC[2]);
        doc.circle(MARGIN + 1.5, y - 1, 1, 'F');
        pLines.forEach(function(l) { doc.text(l, MARGIN + 6, y); y += 5.5; });
        y += 2;
      });
    });
    y += 6;
  }

  /* ── 5. Formules ── */
  if (fi.formules && fi.formules.length) {
    checkPage(16);
    sectionLabel('Formules cles');
    fi.formules.forEach(function(form) {
      if (typeof form === 'object' && form !== null) {
        var expr = _pdfSanitize((form.expr || form.nom || '').trim());
        if (!expr) return;
        doc.setFont('courier', 'bold'); doc.setFontSize(10);
        var exprLines = doc.splitTextToSize(expr, cW - 12);
        var boxH = exprLines.length * 5.8 + 8
          + (form.unite ? 6 : 0)
          + (form.detail ? Math.ceil(_pdfSanitize(form.detail).length / 60) * 5 + 4 : 0);
        checkPage(boxH + 5);
        doc.setFillColor(C_LBLUE[0], C_LBLUE[1], C_LBLUE[2]);
        doc.roundedRect(MARGIN, y, cW, boxH, 2, 2, 'F');
        doc.setTextColor(C_DARK[0], C_DARK[1], C_DARK[2]);
        exprLines.forEach(function(l, li) { doc.text(l, MARGIN + cW / 2, y + 7 + li * 5.8, { align: 'center' }); });
        var dy = y + 7 + exprLines.length * 5.8;
        if (form.unite) {
          doc.setFont('helvetica', 'normal'); doc.setFontSize(7.5);
          doc.setTextColor(C_GRAY[0], C_GRAY[1], C_GRAY[2]);
          doc.text('Unite : ' + _pdfSanitize(form.unite), MARGIN + 6, dy + 3);
          dy += 6;
        }
        if (form.detail) {
          doc.setFont('helvetica', 'italic'); doc.setFontSize(8);
          doc.setTextColor(C_TEXT[0], C_TEXT[1], C_TEXT[2]);
          doc.splitTextToSize(_pdfSanitize(form.detail), cW - 12).forEach(function(l, li) {
            doc.text(l, MARGIN + 6, dy + 3 + li * 5);
          });
        }
        y += boxH + 5;
      } else {
        form.split(' | ').forEach(function(part) {
          part = _pdfSanitize(part.trim());
          if (!part) return;
          doc.setFont('courier', 'bold'); doc.setFontSize(10);
          var partLines = doc.splitTextToSize(part, cW - 12);
          var boxH = partLines.length * 5.8 + 8;
          checkPage(boxH + 5);
          doc.setFillColor(C_LBLUE[0], C_LBLUE[1], C_LBLUE[2]);
          doc.roundedRect(MARGIN, y, cW, boxH, 2, 2, 'F');
          doc.setTextColor(C_DARK[0], C_DARK[1], C_DARK[2]);
          partLines.forEach(function(l, li) { doc.text(l, MARGIN + cW / 2, y + 7 + li * 5.8, { align: 'center' }); });
          y += boxH + 5;
        });
      }
    });
    y += 3;
  }

  /* ── 6. À retenir ── */
  if (fi.retenir) {
    var retenirItems = _pdfSanitize(fi.retenir).split(' | ').map(function(p){ return p.trim(); }).filter(Boolean);
    checkPage(16);
    sectionLabel('A retenir');
    retenirItems.forEach(function(item) {
      doc.setFont('helvetica', 'bold'); doc.setFontSize(9.5);
      var itemLines = doc.splitTextToSize(item, cW - 10);
      checkPage(itemLines.length * 5.5 + 5);
      doc.setFillColor(C_ACC[0], C_ACC[1], C_ACC[2]);
      doc.circle(MARGIN + 1.5, y - 1, 1, 'F');
      doc.setTextColor(C_DARK[0], C_DARK[1], C_DARK[2]);
      itemLines.forEach(function(l) { doc.text(l, MARGIN + 6, y); y += 5.5; });
      y += 3;
    });
    y += 4;
  }

  /* ── 7. Schéma hydraulique ── */
  if (fi.schema) {
    if (schemaPng && schemaPng.dataUrl) {
      var imgH = Math.round(schemaPng.h * (cW / schemaPng.w));
      checkPage(imgH + 22);
      sectionLabel('Schema hydraulique');
      doc.setDrawColor(C_LBLUE[0], C_LBLUE[1], C_LBLUE[2]);
      doc.setLineWidth(0.3);
      doc.roundedRect(MARGIN, y, cW, imgH + 4, 2, 2, 'D');
      doc.addImage(schemaPng.dataUrl, 'PNG', MARGIN + 2, y + 2, cW - 4, imgH);
      y += imgH + 8;
      doc.setFont('helvetica', 'italic'); doc.setFontSize(8);
      doc.setTextColor(C_GRAY[0], C_GRAY[1], C_GRAY[2]);
      doc.text('Figure 1  —  ' + _pdfSanitize(c.titre), MARGIN + cW / 2, y, { align: 'center' });
      y += 10;
    } else {
      checkPage(20);
      doc.setFillColor(C_LGRAY[0], C_LGRAY[1], C_LGRAY[2]);
      doc.setDrawColor(C_LBLUE[0], C_LBLUE[1], C_LBLUE[2]);
      doc.setLineWidth(0.3);
      doc.roundedRect(MARGIN, y, cW, 14, 2, 2, 'FD');
      doc.setFont('helvetica', 'italic'); doc.setFontSize(8.5);
      doc.setTextColor(C_GRAY[0], C_GRAY[1], C_GRAY[2]);
      doc.text('Schema disponible dans l\'application HydroCalc', MARGIN + cW / 2, y + 8, { align: 'center' });
      y += 18;
    }
  }

  /* ── 8. Exercices d'application ── */
  if (c.exercices && c.exercices.length) {
    newPage();
    sectionLabel('Exercices d\'application');

    c.exercices.forEach(function(ex, ei) {
      checkPage(40);
      var exNum = (ei + 1) < 10 ? '0' + (ei + 1) : '' + (ei + 1);

      /* En-tête exercice */
      doc.setFillColor(C_LGRAY[0], C_LGRAY[1], C_LGRAY[2]);
      doc.roundedRect(MARGIN, y, cW, 9, 2, 2, 'F');
      doc.setFillColor(C_DARK[0], C_DARK[1], C_DARK[2]);
      doc.roundedRect(MARGIN, y, 14, 9, 2, 2, 'F');
      doc.setFont('helvetica', 'bold'); doc.setFontSize(8);
      doc.setTextColor(255, 255, 255);
      doc.text(exNum, MARGIN + 7, y + 6.2, { align: 'center' });
      doc.setFontSize(9.5); doc.setTextColor(C_DARK[0], C_DARK[1], C_DARK[2]);
      var exTitre = ex.titre ? _pdfSanitize(ex.titre) : 'Exercice ' + exNum;
      doc.text(exTitre, MARGIN + 17, y + 6.2);
      y += 11;

      if (ex.source || ex.difficulte) {
        doc.setFont('helvetica', 'italic'); doc.setFontSize(7.5);
        doc.setTextColor(C_GRAY[0], C_GRAY[1], C_GRAY[2]);
        var srcTxt = [ex.source, ex.difficulte ? 'Niveau : ' + ex.difficulte : ''].filter(Boolean).join('  ·  ');
        doc.text(_pdfSanitize(srcTxt), MARGIN + 17, y + 4);
        y += 8;
      }

      if (ex.enonce) {
        doc.setFont('helvetica', 'normal'); doc.setFontSize(9.5);
        var enonceLines = doc.splitTextToSize(_pdfSanitize(ex.enonce), cW - 10);
        checkPage(enonceLines.length * 5.5 + 12);
        doc.setFillColor(C_LGRAY[0], C_LGRAY[1], C_LGRAY[2]);
        doc.roundedRect(MARGIN, y, cW, enonceLines.length * 5.5 + 8, 2, 2, 'F');
        doc.setFillColor(C_ACC[0], C_ACC[1], C_ACC[2]);
        doc.roundedRect(MARGIN, y, 2.5, enonceLines.length * 5.5 + 8, 1, 1, 'F');
        doc.setTextColor(C_TEXT[0], C_TEXT[1], C_TEXT[2]);
        enonceLines.forEach(function(l, li) { doc.text(l, MARGIN + 7, y + 6.5 + li * 5.5); });
        y += enonceLines.length * 5.5 + 12;
      }

      if (ex.schema) {
        var exPng = schemaMap ? (schemaMap['ex_' + ex.id] || null) : null;
        if (exPng && exPng.dataUrl) {
          var exImgH = Math.round(exPng.h * (cW / exPng.w));
          checkPage(exImgH + 12);
          doc.addImage(exPng.dataUrl, 'PNG', MARGIN, y, cW, exImgH);
          y += exImgH + 4;
          doc.setFont('helvetica', 'italic'); doc.setFontSize(8);
          doc.setTextColor(C_GRAY[0], C_GRAY[1], C_GRAY[2]);
          doc.text('Figure  —  ' + exTitre, MARGIN + cW / 2, y, { align: 'center' });
          y += 8;
        } else {
          checkPage(18);
          doc.setFillColor(C_LGRAY[0], C_LGRAY[1], C_LGRAY[2]);
          doc.setDrawColor(C_LBLUE[0], C_LBLUE[1], C_LBLUE[2]);
          doc.setLineWidth(0.3);
          doc.roundedRect(MARGIN, y, cW, 12, 2, 2, 'FD');
          doc.setFont('helvetica', 'italic'); doc.setFontSize(8);
          doc.setTextColor(C_GRAY[0], C_GRAY[1], C_GRAY[2]);
          doc.text('Voir schema dans l\'application HydroCalc', MARGIN + cW / 2, y + 7, { align: 'center' });
          y += 16;
        }
      }

      if (ex.questions && ex.questions.length) {
        ex.questions.forEach(function(q) {
          doc.setFont('helvetica', 'normal'); doc.setFontSize(9.5);
          var qLines = doc.splitTextToSize(_pdfSanitize(q.texte), cW - 14);
          doc.setFont('helvetica', 'italic'); doc.setFontSize(8);
          var indiceLines = q.indice ? doc.splitTextToSize('Indice : ' + _pdfSanitize(q.indice), cW - 12) : [];
          var ansLines = 4;
          var blockH = qLines.length * 5.5 + 8 + (indiceLines.length ? indiceLines.length * 4.8 + 6 : 0) + ansLines * 7 + 6;
          checkPage(blockH);

          doc.setFillColor(C_LBLUE[0], C_LBLUE[1], C_LBLUE[2]);
          doc.roundedRect(MARGIN, y, cW, qLines.length * 5.5 + 8, 1.5, 1.5, 'F');
          doc.setFont('helvetica', 'bold'); doc.setFontSize(9.5);
          doc.setTextColor(C_DARK[0], C_DARK[1], C_DARK[2]);
          doc.text('Q' + q.num + '.', MARGIN + 4, y + 6.5);
          doc.setFont('helvetica', 'normal'); doc.setTextColor(C_TEXT[0], C_TEXT[1], C_TEXT[2]);
          qLines.forEach(function(l, li) { doc.text(l, MARGIN + 13, y + 6.5 + li * 5.5); });
          y += qLines.length * 5.5 + 10;

          if (indiceLines.length) {
            doc.setFont('helvetica', 'italic'); doc.setFontSize(8);
            doc.setTextColor(C_GRAY[0], C_GRAY[1], C_GRAY[2]);
            indiceLines.forEach(function(l, li) { doc.text(l, MARGIN + 6, y + li * 4.8); });
            y += indiceLines.length * 4.8 + 5;
          }

          doc.setDrawColor(200, 212, 225); doc.setLineWidth(0.25);
          for (var li = 0; li < ansLines; li++) {
            var lx1 = MARGIN + 3, lx2 = MARGIN + cW - 3, ly = y + li * 7 + 4;
            var sx = lx1;
            while (sx < lx2) { doc.line(sx, ly, Math.min(sx + 1.5, lx2), ly); sx += 3.5; }
          }
          y += ansLines * 7 + 8;
        });
      }
      y += 8;
    });
  }

  return y;
}

/* ─── Rendu d'un tableau Markdown dans le PDF ─── */
function _pdfRenderMarkdownTable(doc, tableBlock, x, y, maxW, col, colL, checkPage) {
  var lines = tableBlock.trim().split('\n').filter(function(l){ return l.trim(); });
  var rows = [];
  lines.forEach(function(l) {
    if (/^\|[-|: ]+\|$/.test(l.trim())) return;
    var cells = l.trim().replace(/^\||\|$/g,'').split('|').map(function(c){ return c.replace(/\*\*/g,'').trim(); });
    rows.push(cells);
  });
  if (!rows.length) return y;
  var numCols = rows.reduce(function(max, r){ return Math.max(max, r.length); }, 0);
  var colW = maxW / numCols;
  var cellH = 6.5;
  var PAGE_H = 278, RESUME_Y = 14;
  rows.forEach(function(row, ri) {
    var isHeader = ri === 0;
    /* Saut de page géré localement avec le y de cette fonction */
    if (y + cellH + 1 > PAGE_H) { doc.addPage(); y = RESUME_Y; }
    if (isHeader) { doc.setFillColor.apply(doc, col); } else { doc.setFillColor(248, 250, 252); }
    doc.rect(x, y, maxW, cellH, 'F');
    doc.setDrawColor(210, 215, 220); doc.setLineWidth(0.2);
    doc.rect(x, y, maxW, cellH, 'D');
    row.forEach(function(cell, ci) {
      doc.setFont('helvetica', isHeader ? 'bold' : 'normal');
      doc.setFontSize(8);
      doc.setTextColor.apply(doc, isHeader ? [255,255,255] : [50,60,55]);
      var cellTxt = _pdfSanitize(cell).slice(0, 40);
      doc.text(cellTxt, x + ci * colW + 2, y + 4.3, { maxWidth: colW - 3 });
    });
    y += cellH;
  });
  return y + 4;
}

function _hexToRgb(hex) {
  hex = (hex || '#0A7460').replace('#', '');
  if (hex.length === 3) hex = hex.split('').map(function(c){ return c + c; }).join('');
  var num = parseInt(hex, 16);
  return [(num >> 16) & 255, (num >> 8) & 255, num & 255];
}

function _pdfFicheHeader(doc, W, MARGIN, color, title, subtitle) {
  var today = new Date().toLocaleDateString('fr-FR');
  var C_DARK = [18, 59, 114];
  var C_ACC  = [8, 127, 234];
  var C_GRAY = [104, 117, 133];

  /* Logo complet à gauche */
  if (_pdfIconDataUrl) {
    doc.addImage(_pdfIconDataUrl, 'PNG', MARGIN, 3, 34, 11);
  } else {
    doc.setFont('helvetica', 'bold'); doc.setFontSize(11);
    doc.setTextColor(C_DARK[0], C_DARK[1], C_DARK[2]);
    doc.text('HydroCalc', MARGIN, 10.5);
  }

  /* Métadonnées à droite */
  var metaParts = [];
  if (subtitle) metaParts.push(_pdfSanitize(subtitle));
  if (title) metaParts.push(_pdfSanitize(title));
  doc.setFont('helvetica', 'normal'); doc.setFontSize(7.5);
  doc.setTextColor(C_GRAY[0], C_GRAY[1], C_GRAY[2]);
  if (metaParts.length) doc.text(metaParts.join('  ·  '), W - MARGIN, 8, { align: 'right' });
  doc.text(today, W - MARGIN, 13.5, { align: 'right' });

  /* Ligne bleue fine */
  doc.setDrawColor(C_ACC[0], C_ACC[1], C_ACC[2]);
  doc.setLineWidth(0.6);
  doc.line(MARGIN, 17, W - MARGIN, 17);
}

/* ─── Aperçu PDF avant téléchargement ─── */
function _pdfSaveOrPreview(doc, filename, toastMsg) {
  var s = (typeof _getSettings === 'function') ? _getSettings() : {};
  var pref = s.pdf_preview || 'always';
  if (pref === 'never') {
    doc.save(filename);
    if (typeof authToast === 'function') authToast(toastMsg || 'PDF téléchargé ✓');
    return;
  }
  var blob = doc.output('blob');
  var blobUrl = URL.createObjectURL(blob);
  var old = document.getElementById('hc-pdf-preview');
  if (old) {
    var oldUrl = old.dataset.blobUrl;
    if (oldUrl) URL.revokeObjectURL(oldUrl);
    old.remove();
  }
  var overlay = document.createElement('div');
  overlay.id = 'hc-pdf-preview';
  overlay.dataset.blobUrl = blobUrl;
  overlay.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.88);z-index:99999;display:flex;flex-direction:column';
  overlay.innerHTML =
    '<div style="background:#0f172a;padding:10px 16px;display:flex;align-items:center;justify-content:space-between;flex-shrink:0;gap:10px">'
    + '<div style="color:#fff;font-size:13px;font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">📄 ' + filename + '</div>'
    + '<div style="display:flex;gap:8px;flex-shrink:0">'
      + '<button onclick="_pdfPreviewNeverAgain()" style="padding:6px 12px;background:none;border:1px solid rgba(255,255,255,0.25);color:rgba(255,255,255,0.65);border-radius:8px;font-size:11px;cursor:pointer;font-family:inherit">Ne plus afficher</button>'
      + '<button onclick="_pdfPreviewDownload()" style="padding:6px 14px;background:#059669;border:none;color:#fff;border-radius:8px;font-size:12px;font-weight:700;cursor:pointer;font-family:inherit">⬇️ Télécharger</button>'
      + '<button onclick="_pdfPreviewClose()" style="padding:6px 12px;background:rgba(255,255,255,0.1);border:none;color:#fff;border-radius:8px;font-size:14px;cursor:pointer">✕</button>'
    + '</div></div>'
    + '<iframe src="' + blobUrl + '" style="flex:1;border:none;width:100%;background:#fff"></iframe>';
  document.body.appendChild(overlay);
  window._pdfPreviewBlob = blob;
  window._pdfPreviewFilename = filename;
  window._pdfPreviewToast = toastMsg;
}

function _pdfPreviewClose() {
  var overlay = document.getElementById('hc-pdf-preview');
  if (overlay) {
    var blobUrl = overlay.dataset.blobUrl;
    if (blobUrl) URL.revokeObjectURL(blobUrl);
    overlay.remove();
  }
}

function _pdfPreviewDownload() {
  var overlay = document.getElementById('hc-pdf-preview');
  if (overlay) {
    var blobUrl = overlay.dataset.blobUrl;
    if (blobUrl) URL.revokeObjectURL(blobUrl);
    overlay.remove();
  }
  if (window._pdfPreviewBlob && window._pdfPreviewFilename) {
    var dlUrl = URL.createObjectURL(window._pdfPreviewBlob);
    var a = document.createElement('a');
    a.href = dlUrl;
    a.download = window._pdfPreviewFilename;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(function(){ URL.revokeObjectURL(dlUrl); }, 100);
    if (typeof authToast === 'function') authToast(window._pdfPreviewToast || 'PDF téléchargé ✓');
  }
}

function _pdfPreviewNeverAgain() {
  if (typeof _setSetting === 'function') _setSetting('pdf_preview', 'never');
  _pdfPreviewDownload();
}

function _downloadFichePDF(fId, aId, mId, cId) {
  if (!_coursFicheAccess()) { authToast('Fiches PDF réservées aux plans Pro, Établissement et Admin'); return; }
  if (!window.jspdf) { authToast('Bibliothèque PDF non chargée — vérifiez votre connexion.'); return; }
  var f = _coursGetFormation(fId), m = _coursGetMatiere(fId, aId, mId), c = _coursGetChapitre(fId, aId, mId, cId);
  if (!c || !c.fiche) return;

  _preconvertSchemas([c], function(schemaMap) {
    var jsPDF = window.jspdf.jsPDF;
    var doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
    var W = 210, MARGIN = 14, cW = W - MARGIN * 2, y = 22;
    var hi = { color: m.color, title: m.name, subtitle: f.sigle };

    _pdfFicheHeader(doc, W, MARGIN, m.color, m.name, f.sigle);
    y = _renderFichePdfBlock(doc, m, c, y, MARGIN, cW, schemaMap, hi);

    var totalPages = doc.internal.getNumberOfPages();
    for (var p = 1; p <= totalPages; p++) {
      doc.setPage(p);
      doc.setDrawColor(220, 238, 255); doc.setLineWidth(0.25);
      doc.line(MARGIN, 285, W - MARGIN, 285);
      doc.setFont('helvetica', 'normal'); doc.setFontSize(7);
      doc.setTextColor(104, 117, 133);
      doc.text('HYDROCALC  |  CALCULER. COMPRENDRE. MAITRISER L\'HYDRAULIQUE.', MARGIN, 290);
      doc.text('Page ' + p + ' / ' + totalPages, W - MARGIN, 290, { align: 'right' });
    }

    _pdfSaveOrPreview(doc, 'Fiche_' + c.titre.replace(/[^a-zA-Z0-9]/g, '_').slice(0, 50) + '.pdf', 'Fiche PDF téléchargée ✓');
  });
}

function _downloadFormationPDF(fId) {
  if (!_coursFicheAccess()) { authToast('Fiches PDF réservées aux plans Pro, Établissement et Admin'); return; }
  if (!window.jspdf) { authToast('Bibliothèque PDF non chargée — vérifiez votre connexion.'); return; }
  var f = _coursGetFormation(fId);
  if (!f) return;

  var allChaps = [];
  f.annees.forEach(function(a) { a.matieres.forEach(function(m) { m.chapitres.forEach(function(c) { if (c.fiche) allChaps.push(c); }); }); });
  var totalChap = allChaps.length;

  _preconvertSchemas(allChaps, function(schemaMap) {
    var jsPDF = window.jspdf.jsPDF;
    var doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
    var W = 210, MARGIN = 14, cW = W - MARGIN * 2;
    var C_DARK = [18, 59, 114], C_ACC = [8, 127, 234], C_GRAY = [104, 117, 133], C_LGRAY = [244, 247, 250];

    /* Page de couverture sobre */
    doc.setFillColor(C_DARK[0], C_DARK[1], C_DARK[2]);
    doc.rect(0, 0, W, 60, 'F');
    if (_pdfIconLightDataUrl) doc.addImage(_pdfIconLightDataUrl, 'PNG', MARGIN, 16, 50, 17);
    else if (_pdfIconDataUrl) doc.addImage(_pdfIconDataUrl, 'PNG', MARGIN, 16, 50, 17);

    doc.setFillColor(C_LGRAY[0], C_LGRAY[1], C_LGRAY[2]);
    doc.rect(0, 60, W, 297 - 60, 'F');

    doc.setFont('helvetica', 'bold'); doc.setFontSize(22);
    doc.setTextColor(C_DARK[0], C_DARK[1], C_DARK[2]);
    doc.text(_pdfSanitize(f.name), MARGIN, 100, { maxWidth: cW });
    doc.setFont('helvetica', 'normal'); doc.setFontSize(11);
    doc.setTextColor(C_GRAY[0], C_GRAY[1], C_GRAY[2]);
    doc.text(_pdfSanitize((f.organisme || '') + (f.niveau ? '  ·  ' + f.niveau : '')), MARGIN, 115);
    doc.setFontSize(9);
    doc.text(totalChap + ' fiches de cours', MARGIN, 125);

    doc.setDrawColor(C_ACC[0], C_ACC[1], C_ACC[2]); doc.setLineWidth(1);
    doc.line(MARGIN, 130, MARGIN + 30, 130);

    doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
    doc.setTextColor(C_GRAY[0], C_GRAY[1], C_GRAY[2]);
    doc.text(new Date().toLocaleDateString('fr-FR'), MARGIN, 280);

    doc.addPage();

    f.annees.forEach(function(a) {
      a.matieres.forEach(function(m) {
        m.chapitres.forEach(function(c) {
          if (!c.fiche) return;
          var hi = { color: m.color, title: m.name, subtitle: f.sigle + ' · ' + a.name };
          _pdfFicheHeader(doc, W, MARGIN, m.color, m.name, f.sigle + ' · ' + a.name);
          var y = 22;
          y = _renderFichePdfBlock(doc, m, c, y, MARGIN, cW, schemaMap, hi);
          doc.addPage();
        });
      });
    });

    if (doc.internal.getNumberOfPages() > 1) doc.deletePage(doc.internal.getNumberOfPages());

    var totalPages = doc.internal.getNumberOfPages();
    for (var p = 2; p <= totalPages; p++) {
      doc.setPage(p);
      doc.setDrawColor(220, 238, 255); doc.setLineWidth(0.25);
      doc.line(MARGIN, 285, W - MARGIN, 285);
      doc.setFont('helvetica', 'normal'); doc.setFontSize(7);
      doc.setTextColor(104, 117, 133);
      doc.text('HYDROCALC  |  CALCULER. COMPRENDRE. MAITRISER L\'HYDRAULIQUE.', MARGIN, 290);
      doc.text('Page ' + p + ' / ' + totalPages, W - MARGIN, 290, { align: 'right' });
    }

    _pdfSaveOrPreview(doc, 'HydroCalc_' + f.sigle.replace(/[^a-zA-Z0-9]/g, '_') + '_fiches.pdf', 'Pack PDF téléchargé (' + totalChap + ' fiches) ✓');
  });
}

function _downloadMatierePDF(fId, aId, mId) {
  if (!_coursFicheAccess()) { authToast('Fiches PDF réservées aux plans Pro, Établissement et Admin'); return; }
  if (!window.jspdf) { authToast('Bibliothèque PDF non chargée — vérifiez votre connexion.'); return; }
  var f = _coursGetFormation(fId);
  var a = _coursGetAnnee(fId, aId);
  var m = _coursGetMatiere(fId, aId, mId);
  if (!m) return;
  var chaps = m.chapitres.filter(function(c){ return c.fiche; });
  if (!chaps.length) { authToast('Aucune fiche disponible pour ce thème.'); return; }

  _preconvertSchemas(chaps, function(schemaMap) {
    var jsPDF = window.jspdf.jsPDF;
    var doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
    var W = 210, MARGIN = 14, cW = W - MARGIN * 2;
    var hi = { color: m.color, title: m.name, subtitle: f.sigle + ' · ' + a.name };

    chaps.forEach(function(c, idx) {
      if (idx > 0) doc.addPage();
      _pdfFicheHeader(doc, W, MARGIN, m.color, m.name, f.sigle + ' · ' + a.name);
      var y = 22;
      y = _renderFichePdfBlock(doc, m, c, y, MARGIN, cW, schemaMap, hi);
    });

    var totalPages = doc.internal.getNumberOfPages();
    for (var p = 1; p <= totalPages; p++) {
      doc.setPage(p);
      doc.setDrawColor(220, 238, 255); doc.setLineWidth(0.25);
      doc.line(MARGIN, 285, W - MARGIN, 285);
      doc.setFont('helvetica', 'normal'); doc.setFontSize(7);
      doc.setTextColor(104, 117, 133);
      doc.text('HYDROCALC  |  CALCULER. COMPRENDRE. MAITRISER L\'HYDRAULIQUE.', MARGIN, 290);
      doc.text('Page ' + p + ' / ' + totalPages, W - MARGIN, 290, { align: 'right' });
    }

    _pdfSaveOrPreview(doc, 'HydroCalc_' + m.name.replace(/[^a-zA-Z0-9]/g, '_').slice(0, 50) + '_fiches.pdf', 'Fiches du theme telechargees (' + chaps.length + ') ✓');
  });
}

/* ─── FLASHCARDS ─────────────────────────────────────────────────── */
var FLASH_PRO_WEEKLY_LIMIT = 7;

function _coursUserPlan() {
  if (typeof AUTH !== 'undefined' && AUTH.user) return AUTH.user.plan || 'free';
  return 'guest';
}

function _coursFlashAccess() {
  var p = _coursUserPlan();
  if (p === 'etab' || p === 'admin') return 'unlimited';
  if (p === 'pro')                   return 'limited';
  return 'none';
}

/* ── Compteur hebdomadaire Pro ── */
function _flashWeekKey() {
  var u = (typeof AUTH !== 'undefined' && AUTH.user) ? AUTH.user.email : 'guest';
  var now = new Date();
  var startOfYear = new Date(now.getFullYear(), 0, 1);
  var week = Math.floor((now - startOfYear) / 604800000);
  return 'hc_flash_week_' + u + '_' + now.getFullYear() + '_' + week;
}

function _flashWeekCount() {
  return parseInt(localStorage.getItem(_flashWeekKey()) || '0', 10);
}

function _flashWeekIncrement() {
  var key = _flashWeekKey();
  localStorage.setItem(key, (_flashWeekCount() + 1).toString());
}

function _flashWeekRemaining() {
  return Math.max(0, FLASH_PRO_WEEKLY_LIMIT - _flashWeekCount());
}

function startFlashcards(fId, aId, mId, cId) {
  var access = _coursFlashAccess();
  var m = _coursGetMatiere(fId, aId, mId);
  var c = _coursGetChapitre(fId, aId, mId, cId);

  if (access === 'none') {
    _coursState.fId = fId; _coursState.aId = aId; _coursState.mId = mId; _coursState.cId = cId;
    _renderFlashcardPaywall(m, (c && c.flashcards) ? c.flashcards.length : 0, 'none');
    return;
  }

  if (access === 'limited' && _flashWeekRemaining() === 0) {
    _coursState.fId = fId; _coursState.aId = aId; _coursState.mId = mId; _coursState.cId = cId;
    _renderFlashcardPaywall(m, (c && c.flashcards) ? c.flashcards.length : 0, 'weekly');
    return;
  }

  if (access === 'limited') _flashWeekIncrement();

  _coursState.fId = fId; _coursState.aId = aId; _coursState.mId = mId; _coursState.cId = cId;
  _coursState.flashIdx = 0;
  _coursState.flashRevealed = false;
  _coursState.flashScores = [];
  renderFlashcard();
}

function renderFlashcard() {
  var c = _coursGetChapitre(_coursState.fId, _coursState.aId, _coursState.mId, _coursState.cId);
  var m = _coursGetMatiere(_coursState.fId, _coursState.aId, _coursState.mId);
  if (!c || !c.flashcards) return;

  var cards = c.flashcards;
  var idx = _coursState.flashIdx;
  var revealed = _coursState.flashRevealed;

  if (idx >= cards.length) { renderFlashcardScore(); return; }


  var card = cards[idx];
  var prog = Math.round((idx / cards.length) * 100);

  var html = '<div style="min-height:100vh;background:var(--c-bg);display:flex;flex-direction:column">';

  /* Barre de progression */
  html += '<div style="padding:var(--s-3) var(--s-4) 0">'
    + '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:var(--s-2)">'
      + '<button onclick="renderCoursChapitre(\'' + _coursState.fId + '\',\'' + _coursState.aId + '\',\'' + _coursState.mId + '\',\'' + _coursState.cId + '\')" '
        + 'style="background:none;border:none;font-family:var(--f-body);font-size:12px;color:var(--c-text-3);cursor:pointer;padding:0">← Fiche</button>'
      + '<div style="font-size:11px;font-weight:700;color:var(--c-text-4)">' + (idx+1) + ' / ' + cards.length + '</div>'
    + '</div>'
    + '<div style="height:4px;background:var(--c-border);border-radius:2px;overflow:hidden">'
      + '<div style="height:100%;width:' + prog + '%;background:' + m.color + ';border-radius:2px;transition:width .3s"></div>'
    + '</div></div>';

  /* Carte */
  html += '<div style="flex:1;padding:var(--s-4);display:flex;flex-direction:column;gap:var(--s-3)">';

  /* Recto — question */
  html += '<div style="background:var(--c-surface);border:2px solid ' + m.color + ';border-radius:var(--r-lg);padding:var(--s-4);text-align:center;min-height:120px;display:flex;flex-direction:column;align-items:center;justify-content:center">'
    + '<div style="font-size:10px;font-weight:800;color:' + m.color + ';text-transform:uppercase;letter-spacing:.06em;margin-bottom:var(--s-2)">❓ Question</div>'
    + '<div style="font-size:15px;font-weight:700;color:var(--c-text);line-height:1.5">' + card.q + '</div>'
    + '</div>';

  if (!revealed) {
    /* Bouton retourner */
    html += '<button onclick="_coursReveal()" '
      + 'style="width:100%;padding:14px;background:' + m.color + ';color:#fff;border:none;border-radius:var(--r-md);font-family:var(--f-body);font-size:14px;font-weight:700;cursor:pointer">'
      + '👁 Voir la réponse</button>';
  } else {
    /* Verso — réponse */
    html += '<div style="background:' + m.colorl + ';border:2px solid ' + m.color + ';border-radius:var(--r-lg);padding:var(--s-4)">'
      + '<div style="font-size:10px;font-weight:800;color:' + m.color + ';text-transform:uppercase;letter-spacing:.06em;margin-bottom:var(--s-2)">✅ Réponse</div>'
      + '<div style="font-size:14px;font-weight:700;color:var(--c-text);line-height:1.6;margin-bottom:var(--s-2)">' + card.r + '</div>'
      + (card.expl ? '<div style="font-size:11px;color:var(--c-text-3);line-height:1.6;padding-top:var(--s-2);border-top:1px solid ' + m.color + '30">💡 ' + card.expl + '</div>' : '')
      + '</div>';
    /* Boutons je savais / à revoir */
    html += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:var(--s-2)">'
      + '<button onclick="_coursFlashNext(false)" '
        + 'style="padding:12px;background:var(--c-danger-l,#FDECEA);color:var(--c-danger,#A82018);border:1.5px solid var(--c-danger,#A82018);border-radius:var(--r-md);font-family:var(--f-body);font-size:13px;font-weight:700;cursor:pointer">'
        + '🔁 À revoir</button>'
      + '<button onclick="_coursFlashNext(true)" '
        + 'style="padding:12px;background:var(--c-ok-l,#EAF8F0);color:var(--c-ok,#166038);border:1.5px solid var(--c-ok,#166038);border-radius:var(--r-md);font-family:var(--f-body);font-size:13px;font-weight:700;cursor:pointer">'
        + '✅ Je savais</button>'
      + '</div>';
  }

  html += '</div></div>';
  document.getElementById('main-content').innerHTML = html;
  document.getElementById('main-content').scrollTop = 0;
}

function _coursReveal() {
  _coursState.flashRevealed = true;
  renderFlashcard();
}

function _coursFlashNext(knew) {
  _coursState.flashScores.push(knew);
  _coursState.flashIdx++;
  _coursState.flashRevealed = false;
  renderFlashcard();
}

function renderFlashcardScore() {
  var scores = _coursState.flashScores;
  var total = scores.length;
  var ok = scores.filter(function(s){ return s; }).length;
  var pct = total ? Math.round(ok / total * 100) : 0;
  var m = _coursGetMatiere(_coursState.fId, _coursState.aId, _coursState.mId);
  var c = _coursGetChapitre(_coursState.fId, _coursState.aId, _coursState.mId, _coursState.cId);

  /* ── Sauvegarder la progression ── */
  _saveFlashProgress(_coursState.fId, _coursState.aId, _coursState.mId, _coursState.cId, pct, ok, total);

  var emoji = pct >= 80 ? '🏆' : pct >= 50 ? '💪' : '📖';
  var msg   = pct >= 80 ? 'Excellent ! Maîtrise solide du chapitre.' : pct >= 50 ? 'Bien ! Quelques points à retravailler.' : 'Continue à réviser, tu vas y arriver !';
  var bg    = pct >= 80 ? '#166038' : pct >= 50 ? '#886000' : '#A82018';

  var html = '<div style="padding:var(--s-4);text-align:center">'
    + '<div style="font-size:56px;margin-bottom:var(--s-3)">' + emoji + '</div>'
    + '<div style="font-size:22px;font-weight:800;color:' + bg + ';margin-bottom:var(--s-2)">' + pct + '%</div>'
    + '<div style="font-size:14px;font-weight:700;color:var(--c-text);margin-bottom:4px">' + ok + ' / ' + total + ' cartes réussies</div>'
    + '<div style="font-size:12px;color:var(--c-text-3);margin-bottom:var(--s-4)">' + msg + '</div>'
    + '<div style="background:var(--c-surface);border:1px solid var(--c-border);border-radius:var(--r-md);padding:var(--s-3);margin-bottom:var(--s-3)">'
      + '<div style="font-size:11px;font-weight:700;color:var(--c-text);margin-bottom:4px">' + c.titre + '</div>'
      + '<div style="height:10px;background:var(--c-border);border-radius:5px;overflow:hidden">'
        + '<div style="height:100%;width:' + pct + '%;background:' + bg + ';border-radius:5px;transition:width .5s"></div>'
      + '</div>'
    + '</div>'
    + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:var(--s-2)">'
      + '<button onclick="startFlashcards(\'' + _coursState.fId + '\',\'' + _coursState.aId + '\',\'' + _coursState.mId + '\',\'' + _coursState.cId + '\')" '
        + 'style="padding:12px;background:' + m.color + ';color:#fff;border:none;border-radius:var(--r-md);font-family:var(--f-body);font-size:13px;font-weight:700;cursor:pointer">🔄 Recommencer</button>'
      + '<button onclick="renderCoursChapitre(\'' + _coursState.fId + '\',\'' + _coursState.aId + '\',\'' + _coursState.mId + '\',\'' + _coursState.cId + '\')" '
        + 'style="padding:12px;background:' + m.colorl + ';color:' + m.color + ';border:1.5px solid ' + m.color + ';border-radius:var(--r-md);font-family:var(--f-body);font-size:13px;font-weight:700;cursor:pointer">📚 Revoir la fiche</button>'
    + '</div></div>'
    + '<div class="pb-nav"></div>';

  document.getElementById('main-content').innerHTML = html;
}

function _renderFlashcardPaywall(m, totalCards, reason) {
  var isNone    = reason === 'none';
  var isWeekly  = reason === 'weekly';

  var title   = isNone ? 'Accès non disponible' : 'Quota hebdomadaire atteint';
  var emoji   = isNone ? '🔒' : '📅';
  var message = isNone
    ? 'Les flashcards sont réservées aux abonnés <strong>Pro</strong> et <strong>Établissement</strong>.<br>Le plan Gratuit donne accès aux fiches de cours uniquement.'
    : 'Vous avez utilisé vos <strong>' + FLASH_PRO_WEEKLY_LIMIT + ' sessions Pro</strong> cette semaine.<br>Revenez lundi ou passez à la licence Établissement pour un accès illimité.';

  var html = '<div style="min-height:100vh;background:var(--c-bg);display:flex;flex-direction:column;align-items:center;justify-content:center;padding:32px 24px;text-align:center">'
    + '<div style="font-size:48px;margin-bottom:16px">' + emoji + '</div>'
    + '<div style="font-size:18px;font-weight:800;color:var(--c-text);margin-bottom:8px">' + title + '</div>'
    + '<div style="font-size:13px;color:var(--c-text-3);line-height:1.7;margin-bottom:24px">' + message + '</div>'
    + '<div style="background:var(--c-surface);border:1px solid var(--c-border);border-radius:14px;overflow:hidden;width:100%;max-width:300px;margin-bottom:24px">';

  var plans = isNone
    ? [
        { ico:'⚡', name:'Pro', price:'5,90 €/mois', features:['7 sessions de flashcards / semaine','Calculateurs avancés','Export rapports'], btn:'Passer à Pro', action:'openSidebar()' },
        { ico:'🏛️', name:'Établissement', price:'35 €/mois', features:['Sessions illimitées','Accès tout inclus','Licence professeur'], btn:'Licence Établissement', action:'openSidebar()' },
      ]
    : [
        { ico:'🏛️', name:'Établissement', price:'35 €/mois', features:['Sessions illimitées chaque semaine','Accès tout inclus','Idéal pour les enseignants'], btn:'Passer Établissement', action:'openSidebar()' },
      ];

  plans.forEach(function(p, i) {
    var border = i < plans.length - 1 ? 'border-bottom:1px solid var(--c-border);' : '';
    html += '<div style="padding:14px 16px;' + border + 'text-align:left">'
      + '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px">'
        + '<div style="font-size:14px;font-weight:800;color:var(--c-text)">' + p.ico + ' ' + p.name + '</div>'
        + '<div style="font-size:12px;font-weight:700;color:var(--c-primary)">' + p.price + '</div>'
      + '</div>'
      + p.features.map(function(f){ return '<div style="font-size:11px;color:var(--c-text-3);margin-bottom:3px"><span style="color:var(--c-ok)">✓ </span>' + f + '</div>'; }).join('')
      + '<button onclick="' + p.action + '" style="width:100%;margin-top:10px;padding:9px;background:var(--c-primary);color:#fff;border:none;border-radius:8px;font-size:12px;font-weight:700;cursor:pointer;font-family:var(--f-body)">' + p.btn + '</button>'
      + '</div>';
  });

  html += '</div>';

  if (isNone && _coursUserPlan() === 'free') {
    html += '<button onclick="if(typeof _showTrialOffer===\'function\')_showTrialOffer()" style="width:100%;max-width:300px;padding:13px;background:linear-gradient(135deg,var(--c-primary),#0d9e7e);color:#fff;border:none;border-radius:12px;font-size:14px;font-weight:800;cursor:pointer;font-family:var(--f-body);margin-bottom:10px">🚀 Essai Pro gratuit — 7 jours</button>';
  }

  html += '<button onclick="renderCoursChapitre(\'' + _coursState.fId + '\',\'' + _coursState.aId + '\',\'' + _coursState.mId + '\',\'' + _coursState.cId + '\')" style="width:100%;max-width:300px;padding:11px;background:none;border:1.5px solid var(--c-border);border-radius:12px;font-size:13px;color:var(--c-text-3);cursor:pointer;font-family:var(--f-body)">← Retour à la fiche</button>'
    + '</div><div class="pb-nav"></div>';

  document.getElementById('main-content').innerHTML = html;
  document.getElementById('main-content').scrollTop = 0;
}

/* ═══════════════════════════════════════════════════
   EXERCICES BTS — Liste et détail
═══════════════════════════════════════════════════ */

function startExercices(fId, aId, mId, cId) {
  _coursState.fId = fId; _coursState.aId = aId; _coursState.mId = mId; _coursState.cId = cId;
  var f = _coursGetFormation(fId);
  var m = _coursGetMatiere(fId, aId, mId);
  var c = _coursGetChapitre(fId, aId, mId, cId);
  if (!c || !c.exercices || !c.exercices.length) return;

  var html = _coursBreadcrumb([
    { label: 'Cours', fn: 'renderCours()' },
    { label: f.sigle, fn: 'renderCoursFormation(\'' + fId + '\')' },
    { label: m.name, fn: 'renderCoursMatiere(\'' + fId + '\',\'' + aId + '\',\'' + mId + '\')' },
    { label: c.titre, fn: 'renderCoursChapitre(\'' + fId + '\',\'' + aId + '\',\'' + mId + '\',\'' + cId + '\')' },
    { label: 'Exercices' },
  ]);

  html += '<div style="padding:var(--s-3) var(--s-4) var(--s-2)">'
    + '<div style="font-size:16px;font-weight:800;color:var(--c-text);margin-bottom:2px">📝 Exercices — ' + c.titre + '</div>'
    + '<div style="font-size:12px;color:var(--c-text-3)">Questions type annales BTS · Corrigés détaillés</div>'
    + '</div>';

  var diffColors = { facile: '#166038', moyen: '#7A4F00', difficile: '#8B1A1A' };
  var diffBg    = { facile: '#EAF8F0', moyen: '#FFF8E1', difficile: '#FFF0F0' };

  c.exercices.forEach(function(ex, idx) {
    var dc = diffColors[ex.difficulte] || '#555';
    var db = diffBg[ex.difficulte]    || '#f5f5f5';
    var nq = ex.questions ? ex.questions.length : 0;
    html += '<div style="margin:0 var(--s-4) var(--s-3);background:var(--c-surface);border:1.5px solid var(--c-border);border-radius:var(--r-md);overflow:hidden">'
      + '<div style="padding:var(--s-3) var(--s-4);cursor:pointer;display:flex;align-items:flex-start;gap:var(--s-3)" onclick="renderExerciceDetail(\'' + fId + '\',\'' + aId + '\',\'' + mId + '\',\'' + cId + '\',' + idx + ')">'
        + '<div style="min-width:36px;height:36px;background:' + m.colorl + ';border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:15px;font-weight:800;color:' + m.color + '">' + (idx+1) + '</div>'
        + '<div style="flex:1">'
          + '<div style="font-size:13px;font-weight:700;color:var(--c-text);margin-bottom:4px">' + ex.titre + '</div>'
          + '<div style="font-size:11px;color:var(--c-text-4);margin-bottom:6px">' + ex.source + '</div>'
          + '<div style="display:flex;gap:6px;flex-wrap:wrap">'
            + '<span style="font-size:10px;font-weight:700;padding:2px 8px;border-radius:20px;background:' + db + ';color:' + dc + '">' + ex.difficulte.toUpperCase() + '</span>'
            + '<span style="font-size:10px;color:var(--c-text-4);padding:2px 6px;background:var(--c-surface-2);border-radius:20px">' + nq + ' question' + (nq > 1 ? 's' : '') + '</span>'
          + '</div>'
        + '</div>'
        + '<span style="color:' + m.color + ';font-size:18px;align-self:center">›</span>'
      + '</div>'
    + '</div>';
  });

  html += '<div style="padding:0 var(--s-4) var(--s-4)">'
    + '<button onclick="renderCoursChapitre(\'' + fId + '\',\'' + aId + '\',\'' + mId + '\',\'' + cId + '\')" '
    + 'style="width:100%;padding:11px;background:none;border:1.5px solid var(--c-border);border-radius:var(--r-md);font-size:13px;color:var(--c-text-3);cursor:pointer;font-family:var(--f-body)">← Retour à la fiche</button>'
    + '</div><div class="pb-nav"></div>';

  document.getElementById('main-content').innerHTML = html;
  document.getElementById('main-content').scrollTop = 0;
}

function renderExerciceDetail(fId, aId, mId, cId, exIdx) {
  var f = _coursGetFormation(fId);
  var m = _coursGetMatiere(fId, aId, mId);
  var c = _coursGetChapitre(fId, aId, mId, cId);
  if (!c || !c.exercices || !c.exercices[exIdx]) return;
  var ex = c.exercices[exIdx];

  var diffColors = { facile: '#166038', moyen: '#7A4F00', difficile: '#8B1A1A' };
  var diffBg    = { facile: '#EAF8F0', moyen: '#FFF8E1', difficile: '#FFF0F0' };
  var dc = diffColors[ex.difficulte] || '#555';
  var db = diffBg[ex.difficulte]    || '#f5f5f5';

  var html = _coursBreadcrumb([
    { label: 'Cours', fn: 'renderCours()' },
    { label: f.sigle, fn: 'renderCoursFormation(\'' + fId + '\')' },
    { label: m.name, fn: 'renderCoursMatiere(\'' + fId + '\',\'' + aId + '\',\'' + mId + '\')' },
    { label: c.titre, fn: 'renderCoursChapitre(\'' + fId + '\',\'' + aId + '\',\'' + mId + '\',\'' + cId + '\')' },
    { label: 'Exercices', fn: 'startExercices(\'' + fId + '\',\'' + aId + '\',\'' + mId + '\',\'' + cId + '\')' },
    { label: 'Exercice ' + (exIdx+1) },
  ]);

  html += '<div style="padding:var(--s-3) var(--s-4) 0">'
    + '<div style="display:flex;align-items:center;gap:8px;margin-bottom:4px">'
      + '<span style="font-size:10px;font-weight:700;padding:3px 10px;border-radius:20px;background:' + db + ';color:' + dc + '">' + ex.difficulte.toUpperCase() + '</span>'
    + '</div>'
    + '<div style="font-size:16px;font-weight:800;color:var(--c-text);margin-bottom:2px">' + ex.titre + '</div>'
    + '<div style="font-size:11px;color:var(--c-text-4);margin-bottom:var(--s-3)">' + ex.source + '</div>'
    + '<div style="background:var(--c-surface-2);border-left:3px solid ' + m.color + ';border-radius:0 var(--r-sm) var(--r-sm) 0;padding:var(--s-3);margin-bottom:var(--s-3)">'
      + '<div style="font-size:10px;font-weight:800;color:' + m.color + ';text-transform:uppercase;letter-spacing:.06em;margin-bottom:6px">📋 Énoncé</div>'
      + '<div style="font-size:13px;color:var(--c-text);line-height:1.7">' + ex.enonce + '</div>'
      + (ex.images && ex.images.length
          ? '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:8px;margin-top:12px">'
            + ex.images.map(function(img){
                return '<div style="border-radius:8px;overflow:hidden;border:1px solid var(--c-border);cursor:pointer" onclick="window.open(\''+img.data+'\',\'_blank\')">'
                  + '<img src="' + img.data + '" style="width:100%;display:block" loading="lazy">'
                  + '</div>';
              }).join('')
            + '</div>'
          : '')
      + (ex.schema
          ? '<div style="margin-top:14px;background:var(--c-surface);border:1px solid var(--c-border);border-radius:var(--r-sm);padding:10px;overflow-x:auto">'
              + '<div style="font-size:9px;font-weight:700;color:var(--c-text-4);text-transform:uppercase;letter-spacing:.06em;margin-bottom:8px">🔍 Schéma de l\'énoncé</div>'
              + ex.schema
            + '</div>'
          : '')
    + '</div>'
    + '</div>';

  if (ex.questions && ex.questions.length) {
    ex.questions.forEach(function(q, qi) {
      var qid = 'exq-' + exIdx + '-' + qi;
      html += '<div style="margin:0 var(--s-4) var(--s-3);background:var(--c-surface);border:1.5px solid var(--c-border);border-radius:var(--r-md);overflow:hidden">'
        + '<div style="padding:var(--s-3);border-bottom:1px solid var(--c-border)">'
          + '<div style="display:flex;align-items:flex-start;gap:var(--s-2)">'
            + '<div style="min-width:24px;height:24px;background:' + m.color + ';border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:800;color:#fff">' + q.num + '</div>'
            + '<div style="font-size:13px;color:var(--c-text);line-height:1.6;font-weight:600">' + q.texte + '</div>'
          + '</div>'
        + '</div>'
        + '<div style="display:flex;gap:0;border-top:1px solid var(--c-border)">'
          + '<button onclick="_exToggle(\'' + qid + '-ind\')" style="flex:1;padding:10px;background:none;border:none;border-right:1px solid var(--c-border);font-family:var(--f-body);font-size:12px;font-weight:700;color:#7A4F00;cursor:pointer">💡 Indice</button>'
          + '<button onclick="_exToggle(\'' + qid + '-rep\')" style="flex:1;padding:10px;background:none;border:none;font-family:var(--f-body);font-size:12px;font-weight:700;color:' + m.color + ';cursor:pointer">✅ Corrigé</button>'
        + '</div>'
        + '<div id="' + qid + '-ind" style="display:none;padding:var(--s-3);background:var(--c-warn-l,#FFF8E1);border-top:1px solid var(--c-border)">'
          + '<div style="font-size:10px;font-weight:800;color:var(--c-text-2);margin-bottom:4px">💡 INDICE</div>'
          + '<div style="font-size:12px;color:var(--c-text-2);line-height:1.6">' + q.indice + '</div>'
        + '</div>'
        + '<div id="' + qid + '-rep" style="display:none;padding:var(--s-3);background:var(--c-ok-l,#EAF8F0);border-top:1px solid var(--c-border)">'
          + '<div style="font-size:10px;font-weight:800;color:var(--c-ok);margin-bottom:8px">✅ CORRIGÉ DÉTAILLÉ</div>'
          + _renderCorrigeSteps(q.reponse)
        + '</div>'
      + '</div>';
    });
  }

  var prevBtn = exIdx > 0
    ? '<button onclick="renderExerciceDetail(\'' + fId + '\',\'' + aId + '\',\'' + mId + '\',\'' + cId + '\',' + (exIdx-1) + ')" style="flex:1;padding:11px;background:none;border:1.5px solid var(--c-border);border-radius:var(--r-md);font-size:13px;color:var(--c-text-3);cursor:pointer;font-family:var(--f-body)">← Exercice précédent</button>'
    : '';
  var nextBtn = exIdx < c.exercices.length - 1
    ? '<button onclick="renderExerciceDetail(\'' + fId + '\',\'' + aId + '\',\'' + mId + '\',\'' + cId + '\',' + (exIdx+1) + ')" style="flex:1;padding:11px;background:' + m.color + ';border:none;border-radius:var(--r-md);font-size:13px;color:#fff;font-weight:700;cursor:pointer;font-family:var(--f-body)">Exercice suivant →</button>'
    : '';

  if (prevBtn || nextBtn) {
    html += '<div style="padding:0 var(--s-4) var(--s-3);display:flex;gap:var(--s-2)">' + prevBtn + nextBtn + '</div>';
  }
  html += '<div style="padding:0 var(--s-4) var(--s-3)">'
    + '<button onclick="startExercices(\'' + fId + '\',\'' + aId + '\',\'' + mId + '\',\'' + cId + '\')" '
    + 'style="width:100%;padding:10px;background:none;border:1.5px solid var(--c-border);border-radius:var(--r-md);font-size:12px;color:var(--c-text-3);cursor:pointer;font-family:var(--f-body)">← Tous les exercices</button>'
    + '</div><div class="pb-nav"></div>';

  document.getElementById('main-content').innerHTML = html;
  document.getElementById('main-content').scrollTop = 0;
}

function _exToggle(id) {
  var el = document.getElementById(id);
  if (el) el.style.display = el.style.display === 'none' ? 'block' : 'none';
}

function _renderCorrigeSteps(reponse) {
  if (typeof reponse === 'string') {
    return '<div style="font-size:12px;color:var(--c-text);line-height:1.8;white-space:pre-line">' + reponse + '</div>';
  }
  return reponse.map(function(step) {
    return '<div style="margin-bottom:10px">'
      + '<div style="font-size:10px;font-weight:800;color:var(--c-ok);text-transform:uppercase;letter-spacing:.05em;margin-bottom:4px">▶ ' + step.titre + '</div>'
      + '<div style="font-size:12px;color:var(--c-text);line-height:1.75;white-space:pre-line;background:var(--c-surface);padding:7px 10px;border-radius:6px;border-left:2px solid var(--c-ok)">' + step.detail + '</div>'
    + '</div>';
  }).join('');
}

/* ─── RENDU TEXTE DE SECTION (détection auto des équations) ────── */
function _renderSectionTexte(texte) {
  var lines = texte.split('\n');
  var html = '';
  var listItems = [];
  var listIsColored = false;
  var paraLines = [];
  var defPending = null; // { label, rest }

  function inlinemd(s) {
    return s
      .replace(/\*\*(.+?)\*\*/g, '<strong style="color:var(--c-primary)">$1</strong>')
      .replace(/\*(.+?)\*/g, '<em style="color:var(--c-text-2)">$1</em>')
      .replace(/`(.+?)`/g, '<code style="background:var(--c-primary-l);color:var(--c-primary);padding:1px 6px;border-radius:4px;font-size:11.5px;font-weight:700">$1</code>');
  }

  function flushDef() {
    if (!defPending) return;
    html += '<div style="background:var(--c-primary-l);border-left:4px solid var(--c-primary);border-radius:0 10px 10px 0;padding:10px 14px;margin:8px 0 4px">'
      + '<div style="font-size:12px;font-weight:800;color:var(--c-primary);margin-bottom:2px">' + defPending.label + '</div>'
      + (defPending.rest ? '<div style="font-size:12.5px;color:var(--c-text);line-height:1.7">' + inlinemd(defPending.rest) + '</div>' : '')
      + '</div>';
    defPending = null;
  }

  function flushList() {
    if (!listItems.length) return;
    flushDef();
    if (listIsColored) {
      html += '<div style="display:flex;flex-direction:column;gap:5px;margin:6px 0 12px">';
      listItems.forEach(function(li) {
        var warn = /⚠|ATTENTION|danger|risque|interdit/i.test(li);
        var ok   = /✓|✅|avantage|recommand/i.test(li);
        var bg   = warn ? 'var(--c-warn-l,#FFF8E1)' : ok ? 'var(--c-ok-l,#EAF8F0)' : 'var(--c-surface-2)';
        var bdr  = warn ? 'var(--c-warn,#E65100)' : ok ? 'var(--c-ok,#166038)' : 'var(--c-border)';
        var ico  = warn ? '⚠' : ok ? '✓' : '›';
        html += '<div style="background:'+bg+';border-left:3px solid '+bdr+';border-radius:0 8px 8px 0;padding:7px 12px;display:flex;gap:8px;align-items:flex-start">'
          + '<span style="color:'+bdr+';font-weight:800;font-size:13px;flex-shrink:0;margin-top:1px">'+ico+'</span>'
          + '<span style="font-size:12.5px;color:var(--c-text);line-height:1.7">'+inlinemd(li)+'</span>'
          + '</div>';
      });
      html += '</div>';
    } else {
      html += '<ul style="margin:6px 0 12px 0;padding-left:0;list-style:none;display:flex;flex-direction:column;gap:5px">';
      listItems.forEach(function(li) {
        html += '<li style="font-size:12.5px;color:var(--c-text);line-height:1.7;display:flex;gap:8px;align-items:flex-start">'
          + '<span style="color:var(--c-primary);font-size:14px;flex-shrink:0;margin-top:0px">›</span>'
          + '<span>'+inlinemd(li)+'</span></li>';
      });
      html += '</ul>';
    }
    listItems = [];
    listIsColored = false;
  }

  function flushPara() {
    if (!paraLines.length) return;
    flushDef();
    html += '<p style="font-size:12.5px;color:var(--c-text-2);line-height:1.9;margin:0 0 10px">' + paraLines.join(' ') + '</p>';
    paraLines = [];
  }

  var tableBuffer = [];

  function flushTable() {
    if (!tableBuffer.length) return;
    var rows = tableBuffer.filter(function(r) { return !/^\|[-| :]+\|/.test(r.trim()); });
    html += '<div style="overflow-x:auto;margin:8px 0 14px;border-radius:10px;overflow:hidden;border:1px solid var(--c-border)">'
      + '<table style="width:100%;border-collapse:collapse;font-size:12px">';
    rows.forEach(function(row, ri) {
      var cells = row.split('|').map(function(c) { return c.trim(); }).filter(function(c, ci, a) { return ci > 0 && ci < a.length - 1; });
      var tag = ri === 0 ? 'th' : 'td';
      var bg  = ri === 0 ? 'background:var(--c-primary);' : (ri % 2 === 0 ? 'background:var(--c-surface-2);' : 'background:var(--c-surface);');
      html += '<tr>' + cells.map(function(c) {
        return '<' + tag + ' style="' + bg + 'padding:8px 12px;border-bottom:1px solid var(--c-border);text-align:left;color:' + (ri === 0 ? '#fff' : 'var(--c-text)') + ';font-weight:' + (ri === 0 ? '700' : '400') + '">' + inlinemd(c) + '</' + tag + '>';
      }).join('') + '</tr>';
    });
    html += '</table></div>';
    tableBuffer = [];
  }

  lines.forEach(function(line) {
    var t = line.trim();

    if (/^\|.+\|/.test(t)) {
      flushList(); flushPara(); flushDef();
      tableBuffer.push(t);
      return;
    } else {
      flushTable();
    }

    if (t === '') {
      flushList(); flushPara(); flushDef();
      return;
    }

    /* Titres # ## ### */
    if (/^#{1,4}\s/.test(t)) {
      flushList(); flushPara(); flushDef();
      var level = (t.match(/^(#+)/)||[''])[0].length;
      var htext = t.replace(/^#+\s/, '');
      var sz = level <= 2 ? '13.5px' : '12.5px';
      var top = level <= 2 ? '14px' : '10px';
      html += '<div style="font-size:'+sz+';font-weight:800;color:var(--c-primary);margin:'+top+' 0 6px;padding-bottom:4px;border-bottom:2px solid var(--c-primary-l)">'
        + inlinemd(htext) + '</div>';
      return;
    }

    /* Listes colorées précédées de 🔴🟡🟢✅⚠ */
    if (/^[🔴🟡🟢✅⚠➕➖🔵🟠]/.test(t)) {
      flushPara(); flushDef();
      listIsColored = true;
      listItems.push(t);
      return;
    }

    /* Listes classiques • - * */
    if (/^[•\-]\s/.test(t)) {
      flushPara(); flushDef();
      listItems.push(t.replace(/^[•\-]\s/, ''));
      return;
    }

    /* Définitions : **Terme :** ou **Terme :** reste du texte */
    var defMatch = t.match(/^\*\*(.+?)\s*:?\*\*\s*:?\s*(.*)/);
    if (defMatch && !/^\*\*.*\*\*.*\*\*/.test(t)) {
      flushList(); flushPara(); flushDef();
      defPending = { label: defMatch[1].replace(/:$/, '').trim(), rest: defMatch[2] || '' };
      return;
    }

    /* Formules mathématiques */
    var isEq = /=/.test(t)
      && /[·×\/\^²³ρνμγλξπΔΣ√⁰¹²³⁴⁵⁶⁷⁸⁹_]/.test(t)
      && !/^[•\-\*#\|]/.test(t)
      && t.length < 160
      && !/^\*\*/.test(t);

    if (isEq) {
      flushList(); flushPara(); flushDef();
      html += '<div style="background:var(--c-primary-l);border-left:4px solid var(--c-primary);border-radius:0 10px 10px 0;padding:10px 16px;margin:6px 0 12px;font-family:\'Courier New\',monospace;font-size:13px;font-weight:700;color:var(--c-primary);overflow-x:auto;white-space:nowrap">' + t + '</div>';
    } else {
      flushList(); flushDef();
      paraLines.push(inlinemd(t));
    }
  });

  flushTable();
  flushList();
  flushPara();
  flushDef();
  return html;
}

/* ─── BREADCRUMB ─────────────────────────────────────────────────── */
function _coursBreadcrumb(items) {
  var html = '<div style="padding:var(--s-2) var(--s-4);display:flex;align-items:center;gap:4px;overflow-x:auto;scrollbar-width:none;background:var(--c-surface-2);border-bottom:1px solid var(--c-border)">';
  items.forEach(function(item, i) {
    if (i > 0) html += '<span style="color:var(--c-text-4);font-size:12px">›</span>';
    if (item.fn) {
      html += '<button onclick="' + item.fn + '" style="background:none;border:none;font-family:var(--f-body);font-size:12px;color:var(--c-primary);cursor:pointer;white-space:nowrap;padding:2px 0">' + item.label + '</button>';
    } else {
      html += '<span style="font-size:12px;color:var(--c-text-3);white-space:nowrap;font-weight:600">' + item.label + '</span>';
    }
  });
  html += '</div>';
  return html;
}
